<?php
declare(strict_types=1);
require_once __DIR__.'/config.php';
function login_h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function login_csrf():string{return $_SESSION['login_csrf']??=bin2hex(random_bytes(32));}
if(isset($_GET['logout'])){unset($_SESSION['inventory_user']);session_regenerate_id(true);header('Location: login.php');exit;}
$user=$_SESSION['inventory_user']??null;
if($user){$r=strtolower($user['role']??'');$target=in_array($r,['shop admin','admin'],true)?'admin_dashboard.php':(in_array($r,['technician','tech'],true)?'technician_dashboard.php':'salesperson_dashboard.php');header('Location: views/M1_ManageUser/'.$target);exit;}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals(login_csrf(),(string)($_POST['csrf']??''))){$error='Session expired. Please try again.';}
 else{$username=trim((string)($_POST['username']??''));$stmt=$link->prepare("SELECT user_id,name,username,password_hash,role FROM users WHERE username=? AND user_status='Active' LIMIT 1");$stmt->bind_param('s',$username);$stmt->execute();$account=$stmt->get_result()->fetch_assoc();if($account&&password_verify((string)($_POST['password']??''),(string)$account['password_hash'])){session_regenerate_id(true);$_SESSION['inventory_user']=['id'=>(int)$account['user_id'],'name'=>$account['name'],'username'=>$account['username'],'role'=>$account['role']];$r=strtolower($account['role']);$target=in_array($r,['shop admin','admin'],true)?'admin_dashboard.php':(in_array($r,['technician','tech'],true)?'technician_dashboard.php':'salesperson_dashboard.php');header('Location: views/M1_ManageUser/'.$target);exit;}$error='Invalid username or password, or the account is inactive.';}
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Log in · PRISM</title><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Mono:wght@700&display=swap" rel="stylesheet"><link rel="stylesheet" href="css/prism.css"></head><body class="login-body"><main class="login-layout"><section class="login-promo"><a class="brand" href="login.php"><span class="mark">P</span><span>PRISM</span></a><div class="promo-copy"><span class="promo-tag">PHONE REPAIR INVENTORY MANAGEMENT</span><h1>Every repair.<br><em>Under control.</em></h1><p>A clear workspace for parts, people, and devices on your bench.</p></div><div class="promo-bottom">BUILT FOR THE PEOPLE WHO FIX IT.</div></section><section class="login-panel"><div class="login-card"><span class="eyebrow">YOUR WORKSPACE</span><h2>Welcome back</h2><p class="muted">Sign in with your existing PRISM account.</p><?php if($error!==''):?><div class="flash error"><?=login_h($error)?></div><?php endif?><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=login_h(login_csrf())?>"><label>Username<input class="input" name="username" autocomplete="username" placeholder="Username" required autofocus></label><label>Password<input class="input" type="password" name="password" autocomplete="current-password" placeholder="Password" required></label><button class="btn primary full">Log in <span>→</span></button></form></div></section></main></body></html>